// js
const employment = ctx.subject.employment;
const ytd = get(ctx.balances, 'ytd', {});
const notice_total = get(ctx.subtotals, 'NOTICE_PAY', 0);
const paid_income = get(ytd, 'NOTICE_PAY', 0);
const total =
  get(ytd, 'SEVERANCE', paid_income) - paid_income + get(ctx.subtotals, 'SEVERANCE', notice_total) - notice_total;
// Exempt as in PND1. Severance on these grounds has no exemption and counts under cl.1(d) of Notification No. 45.
const ground = get(employment, 'employee_extension_data.exit_facts.exit_ground', '');
const unexempt = ctx.lookup.severance_taxed_grounds.includes(ground);
const exempt = unexempt
  ? 0
  : Math.min(ctx.lookup.severance_daily_wages_limit * ctx.day_rate, ctx.lookup.severance_exemption_limit);
const income = Math.max(0, total - exempt);
const paid = get(ctx.balances, 'statutory_contribution', {});
const withheld = Object.hasOwn(paid, 'PND1_SEVERANCE.employee') ? paid['PND1_SEVERANCE.employee'] : 0;
if (income <= 0) return -withheld;
const start = employment.effective_range.from;
const end = add_days(get(employment, 'effective_range.to', ctx.as_of), 1);
const whole = Math.trunc(calendar_completed_months(start, end) / 12);
// s.48(5) para 4: 183 days of a part year count as a year; fewer are dropped.
const years = whole + (calendar_distance_days(add_years(start, whole), end) >= ctx.lookup.part_year_days ? 1 : 0);
// Notification No. 45 cl.3(2): cl.1(d) income earns expenses only up to the last month's pay × years.
const base = unexempt ? Math.min(income, ctx.day_rate * ctx.lookup.monthly_divisor * years) : income;
const service = Math.min(ctx.lookup.expense_per_year * years, base);
const expense = service + (base - service) * ctx.lookup.expense_share;
// No 150,000 baht exemption here (Royal Decree No. 470), so the 0 percent band of the ladder drops out.
const tax = ladder(income - expense, ctx.lookup.ladder.slice(1));
return round(tax - withheld, ctx.lookup.rounding_step, 'HALF_UP');

